const EXTENSOES = {
  'application/pdf': 'pdf',
  'image/jpeg': 'jpg',
  'image/jpg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx'
};
const entrada = $('Entrada do Agente').first().json;
const extensao = EXTENSOES[entrada.tipo_anexo] || 'bin';
const relativo = 'whatsapp-uploads/' + String(entrada.id_msg_waha).replace(/[^a-zA-Z0-9_.-]/g, '_') + '.' + extensao;

return [{
  json: { caminho_relativo: relativo, caminho_para_claude: '/shared/' + relativo },
  binary: $('Baixar Anexo').first().binary
}];

const retorno = $json;
const anterior = $('Compor Prompt').first().json.sessao_anterior || null;
const falhou = Boolean(retorno.error);

return [{ json: { falhou, erro: retorno.error || null, sessao_atual: falhou ? anterior : (retorno.sessionId || anterior) } }];
